class SettingsPage extends StatelessWidget {
  final LocalStore store;const SettingsPage({super.key,required this.store});
  Future<void> exportBackup(BuildContext context,{bool rules=false})async=>guarded(context,()async{final ok=await LocalFiles.saveText('${rules?'metzgerapp-regeln':'metzgerapp-backup'}-${today()}.json',store.backup(rulesOnly:rules),'application/json');if(context.mounted&&ok)toast(context,'Datei gespeichert.');});
  Future<void> importBackup(BuildContext context,{bool rules=false})async=>guarded(context,()async{final bytes=await LocalFiles.pick('application/json');if(bytes==null||!context.mounted)return;final rows=store.parseBackup(utf8.decode(bytes),rulesOnly:rules);if(!await confirm(context,rules?'Regeln importieren?':'Alle Daten ersetzen?', '${rows.length} Datensätze. ${rules?'Gleichnamige IDs werden ersetzt, importierte Regeln als ungeprüft markiert.':'Der gesamte lokale Datenbestand wird ersetzt. Vorher unbedingt ein eigenes Backup erstellen.'}'))return;await store.restore(rows,rulesOnly:rules);if(context.mounted)toast(context,'Import abgeschlossen.');});
  Future<void> exportCsv(BuildContext context)async=>guarded(context,()async{final data=<List<dynamic>>[['Typ','Name','Datum','Endgewicht kg','Kosten EUR','Kosten/kg EUR','Planumsatz EUR','Plangewinn EUR','Erfasster Umsatz EUR','Erlös minus Chargenkosten EUR']];for(final kind in ['calculation','production']){for(final row in store.all(kind)){final s=map(row['summary']);if(kind=='production'){final actual=salesTotals(row,store.all('sale'));s['actualRevenue']=actual['revenue'];s['actualBalance']=actual['balance'];}data.add([kind=='production'?'Produktion':'Kalkulation',nameOf(row),str(row['created']),for(final k in ['outputKg','cost','costKg','revenue','profit','actualRevenue','actualBalance'])numOrNull(s[k])==null?'':fmt(n(s[k]),k=='outputKg'?3:2)]);}}final ok=await LocalFiles.csv('metzgerapp-auswertung-${today()}',data);if(context.mounted&&ok)toast(context,'CSV gespeichert.');});
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(context,_)=>PageFrame(title:'Einstellungen',child:ListView(padding:const EdgeInsets.all(12),children:[Section('Darstellung & Standardkosten',[ValueRow('Theme',str(store.settings['theme'])),ValueRow('Steuersatz (Benutzervorgabe)','${fmt(n(store.settings['tax']),2)} %'),OutlinedButton.icon(onPressed:()=>openPage(context,GenericEditor(title:'App-Einstellungen',kind:'settings',initial:store.settings,store:store,notice:'Umsatzsteuer selbst passend zur Nutzung festlegen. Alle Preise auf konsistenter Kostenbasis eingeben.',fields:const [FieldSpec('theme','Darstellung',choices:['System','Hell','Dunkel'],required:true),FieldSpec('textScale','Schriftfaktor (0,9–1,4)',number:true,min:0.9,max:1.4,required:true),FieldSpec('tax','Standard-Umsatzsteuer (%)',number:true,min:0,max:100,required:true),FieldSpec('hourlyRate','Arbeitskosten €/h',number:true,min:0),FieldSpec('electricityRate','Strompreis €/kWh',number:true,min:0),FieldSpec('waterRate','Wasserkosten €/l',number:true,min:0)])),icon:const Icon(Icons.tune),label:const Text('Einstellungen bearbeiten'))]),Section('Datensicherung',[const Notice('Die App speichert Daten ausschließlich lokal. Backups außerhalb des App-Speichers ablegen, z. B. in Downloads oder auf USB/PC. Dateien enthalten vertrauliche Rezept- und Geschäftsdaten; sie sind nicht zusätzlich verschlüsselt.'),FilledButton.icon(onPressed:()=>exportBackup(context),icon:const Icon(Icons.save_alt),label:const Text('Vollständiges Backup exportieren')),OutlinedButton.icon(onPressed:()=>importBackup(context),icon:const Icon(Icons.restore),label:const Text('Backup wiederherstellen')),OutlinedButton.icon(onPressed:()=>exportCsv(context),icon:const Icon(Icons.table_chart_outlined),label:const Text('Kalkulationen als CSV exportieren'))]),Section('Vorschriften aktualisieren',[const Notice('Keine automatische Online-Aktualisierung. Rechtsstand manuell prüfen. Importierte Prüfregeln bleiben gesperrt, bis sie fachlich freigegeben werden.'),OutlinedButton.icon(onPressed:()=>exportBackup(context,rules:true),icon:const Icon(Icons.download),label:const Text('Regeldatei exportieren')),OutlinedButton.icon(onPressed:()=>importBackup(context,rules:true),icon:const Icon(Icons.upload),label:const Text('Regeldatei importieren'))]),Section('Eigene Stammdaten',[ListTile(title:const Text('Eigene Rezeptkategorien'),trailing:const Icon(Icons.chevron_right),onTap:()=>openPage(context,simpleList(context,store,'category','Rezeptkategorien',const [FieldSpec('name','Kategorie',required:true)]))),ListTile(title:const Text('Eigene Tierarten'),trailing:const Icon(Icons.chevron_right),onTap:()=>openPage(context,simpleList(context,store,'animal','Tierarten',const [FieldSpec('name','Tierart',required:true)])))]),const Notice('MetzgerApp 2.0 · Offline · Keine Anmeldung, Werbung oder Telemetrie. Fachliche Prüfung vor gewerblicher Nutzung.')])));
}
class StatisticsPage extends StatelessWidget {
  final LocalStore store;const StatisticsPage({super.key,required this.store});
  @override Widget build(BuildContext context)=>AnimatedBuilder(animation:store,builder:(context,_) {final entries=store.all('production'),plans=store.all('calculation');final groups=<String,List<Json>>{};for(final r in entries){groups.putIfAbsent(nameOf(r),()=>[]).add(r);}double sum(List<Json> rows,String key)=>rows.fold(0.0,(s,r)=>s+n(map(r['summary'])[key]));final sales=store.all('sale');final sold=entries.where((r)=>salesTotals(r,sales)['revenue']!=null).toList();double salesSum(String key)=>sold.fold(0.0,(s,r)=>s+n(salesTotals(r,sales)[key]));final byProduct=groups.entries.toList()..sort((a,b)=>sum(b.value,'profit').compareTo(sum(a.value,'profit')));final priceHistory=store.all('priceHistory')..sort((a,b)=>str(b['created']).compareTo(str(a['created'])));return PageFrame(title:'Statistiken',child:ListView(padding:const EdgeInsets.all(12),children:[const Notice('Planwerte und tatsächlich erfasste Verkäufe werden getrennt ausgewertet. Wiederholte Kalkulationen werden nicht als Produktion gezählt.'),Section('Produktionen',[ValueRow('Anzahl','${entries.length}'),ValueRow('Endgewicht','${fmt(sum(entries,'outputKg'))} kg'),ValueRow('Erfasste Gesamtkosten',money(sum(entries,'cost'))),ValueRow('Produktionen mit Verkaufspreis','${entries.where((r)=>map(r['summary'])['profit']!=null).length}'),ValueRow('Möglicher Gewinn (nur bewertete Chargen)',money(sum(entries,'profit'))),ValueRow('Gespeicherte separate Kalkulationen','${plans.length}')]),Section('Erfasste Verkäufe',[ValueRow('Chargen mit erfasstem Verkauf','${sold.length}'),ValueRow('Nettoerlös',money(salesSum('revenue'))),ValueRow('Erlös minus gesamte Kosten dieser Chargen',money(salesSum('balance')))]),Section('Produkte – Planwerte',[if(byProduct.isEmpty)const Text('Noch keine Produktionen.'),for(final group in byProduct)...[Text(group.key,style:Theme.of(context).textTheme.titleMedium),ValueRow('Menge','${fmt(sum(group.value,'outputKg'))} kg'),ValueRow('Kosten',money(sum(group.value,'cost'))),ValueRow('Kalkulierter Gewinn',group.value.any((r)=>map(r['summary'])['profit']!=null)?money(sum(group.value,'profit')):'–'),const Divider()]]),Section('Letzte Preisänderungen',[if(priceHistory.isEmpty)const Text('Noch keine Preisstände.'),for(final row in priceHistory.take(30))ListTile(contentPadding:EdgeInsets.zero,title:Text(nameOf(row)),subtitle:Text(dateLabel(row['created'])),trailing:Text('${shownMoney(row['buyPrice'])} / ${fmt(n(row['buyQuantity']))} ${str(row['buyUnit'])}'))]) ]));});
}
